query ServiceFeeAmount($merchant_uid: String!, $amount: Int!) {
  serviceFeeAmount(merchant_uid: $merchant_uid, amount: $amount) {
    ach {
      fee
      total
      adjusted_total
    }
    card {
      fee
      total
      adjusted_total
    }
  }
}

